const schema = JSON.parse(pm.collectionVariables.get("AWALL_jsonSchema"));
const jsonData = pm.response.json();
const list = Array.isArray(jsonData.data) ? jsonData.data : [];

const JUMLAH_SEED = 3;
const seedPertama = {
    id: 1,
    warga_id: 1,
    nama_lengkap: "Agus Santoso",
    email: "agus.santoso@contoh.id",
    peran: "admin"
};

const bacaJson = (nama) => {
    try {
        return JSON.parse(pm.collectionVariables.get(nama));
    } catch (e) {
        return null;
    }
};

const akunId = Number(pm.collectionVariables.get("akun_id"));
const adaAkunBaru = Number.isInteger(akunId) && akunId > 0;
const expected = bacaJson("akun_terakhir");
const akunBaru = list.find((item) => item.id === akunId);
const terakhir = list[list.length - 1];

pm.test("Status code harus 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Body sesuai JSON Schema", function () {
    pm.response.to.have.jsonSchema(schema);
});

pm.test("status bernilai success", function () {
    pm.expect(jsonData.status).to.eql("success");
});

pm.test("Content-Type berupa JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("data berupa array dan tidak kosong", function () {
    pm.expect(jsonData.data).to.be.an("array");
    pm.expect(jsonData.data).to.not.be.empty;
});

pm.test("total sama dengan jumlah data", function () {
    pm.expect(jsonData.total).to.eql(list.length);
});

pm.test("Data pertama adalah akun seed (id 1)", function () {
    pm.expect(list[0]).to.include(seedPertama);
});

if (adaAkunBaru) {
    pm.test("Akun hasil POST ada di daftar", function () {
        pm.expect(akunBaru, `akun dengan id ${akunId} tidak ditemukan`).to.not.be.undefined;
    });

    pm.test("Akun hasil POST adalah data terakhir", function () {
        pm.expect(terakhir.id).to.eql(akunId);
    });

    pm.test("Isi akun sesuai data terbaru (hasil POST/PUT)", function () {
        pm.expect(expected, "akun_terakhir kosong, jalankan POST dulu").to.not.be.null;
        pm.expect(akunBaru).to.eql(expected);
    });

    pm.test("Jumlah data bertambah dari seed", function () {
        pm.expect(list.length).to.be.at.least(JUMLAH_SEED + 1);
    });
} else {
    pm.test("Belum ada akun baru: jumlah data sesuai seed", function () {
        pm.expect(list.length).to.eql(JUMLAH_SEED);
    });
}

pm.test("Data terurut berdasarkan id (naik)", function () {
    const ids = list.map((item) => item.id);
    const sorted = [...ids].sort((a, b) => a - b);
    pm.expect(ids).to.eql(sorted);
});

pm.test("Setiap data memiliki kolom lengkap dan peran valid", function () {
    list.forEach((item) => {
        pm.expect(item).to.have.all.keys(
            "id", "warga_id", "nama_lengkap", "email", "peran", "created_at"
        );
        pm.expect(item.peran).to.be.oneOf(["warga", "admin"]);
    });
});

pm.test("Email setiap akun unik", function () {
    const emails = list.map((item) => item.email);
    pm.expect(new Set(emails).size).to.eql(emails.length);
});

pm.test("warga_id setiap akun unik (relasi one to one)", function () {
    const ids = list.map((item) => item.warga_id);
    pm.expect(new Set(ids).size).to.eql(ids.length);
});

pm.test("password dan password_hash tidak bocor", function () {
    list.forEach((item) => {
        pm.expect(item).to.not.have.property("password");
        pm.expect(item).to.not.have.property("password_hash");
    });
});

pm.test("Response time di bawah 500 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(500);
});

