    pm.expect(data).to.not.be.an("array");
    pm.expect(jsonData).to.not.have.property("total");
});

pm.test("id pada data sama dengan id di URL", function () {
    pm.expect(data.id).to.eql(idDiUrl);
});

pm.test(`Data sesuai (${sumber})`, function () {
    pm.expect(expected, `Tidak ada data pembanding untuk id ${idDiUrl}`).to.not.be.null;
    pm.expect(data).to.include(expected);
});

pm.test("Kolom lengkap dan tipe data benar", function () {
    pm.expect(data).to.have.all.keys(
        "id", "warga_id", "nama_lengkap", "email", "peran", "created_at"
    );
    pm.expect(data.id).to.be.a("number");
    pm.expect(data.warga_id).to.be.a("number");
    pm.expect(data.nama_lengkap).to.be.a("string");
