    dikirim = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
} catch (e) {
    dikirim = {};
}

// Data yang diharapkan = data sebelumnya + kolom yang diubah
const harapan = { ...sebelum };
if (dikirim.email !== undefined) harapan.email = String(dikirim.email).toLowerCase();
if (dikirim.peran !== undefined) harapan.peran = dikirim.peran;

// Perbarui pembanding hanya kalau yang diubah memang akun hasil POST
