    if (dikirim.email !== undefined) pm.expect(data.email).to.eql(String(dikirim.email).toLowerCase());
    if (dikirim.peran !== undefined) pm.expect(data.peran).to.eql(dikirim.peran);
});

pm.test("Kolom lain tidak berubah (warga_id, nama_lengkap, created_at)", function () {
    pm.expect(sebelum, "akun_terakhir kosong, jalankan POST dulu").to.have.property("id");
    pm.expect(data.warga_id).to.eql(sebelum.warga_id);
    pm.expect(data.nama_lengkap).to.eql(sebelum.nama_lengkap);
    pm.expect(data.created_at).to.eql(sebelum.created_at);
});

pm.test("Seluruh data sesuai harapan", function () {
    pm.expect(data).to.eql(harapan);
});

pm.test("password dan password_hash tidak bocor", function () {
    pm.expect(data).to.not.have.property("password");
    pm.expect(data).to.not.have.property("password_hash");
});

pm.test("Response time di bawah 500 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(500);
});
